"use client"

import { useState, useEffect } from "react"
import axios from "axios"
import { Edit, Trash2, Plus, AlertCircle, Loader2, Search, Filter } from "lucide-react"
import Layout from "../Layout"
import EditCriterionModal from "./EditCriterionModal"
import CreateCriterionModal from "./CreateCriterionModal"

export default function CriteriaTable() {
  const [criteria, setCriteria] = useState([])
  const [error, setError] = useState("")
  const [isLoading, setIsLoading] = useState(true)
  const [isEditModalOpen, setIsEditModalOpen] = useState(false)
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false)
  const [selectedCriterion, setSelectedCriterion] = useState(null)
  const [searchTerm, setSearchTerm] = useState("")

  // Charger les critères depuis le backend
  useEffect(() => {
    fetchCriteria()
  }, [])

  const fetchCriteria = async () => {
    setIsLoading(true)
    setError("")
    const token = localStorage.getItem("token")
    if (!token) {
      setError("Authentification requise. Veuillez vous connecter.")
      setIsLoading(false)
      return
    }

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/criteria`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      setCriteria(response.data)
    } catch (error) {
      const errorMsg = error.response?.data?.message || "Échec du chargement des critères."
      setError(errorMsg)
    } finally {
      setIsLoading(false)
    }
  }

  // Gérer les changements dans la description
  const handleDescriptionChange = async (criteriaId, caseIndex, newDescription) => {
    const updatedCriteria = criteria.map((criterion) =>
      criterion._id === criteriaId
        ? {
            ...criterion,
            cases: criterion.cases.map((c, i) => (i === caseIndex ? { ...c, description: newDescription } : c)),
          }
        : criterion,
    )
    setCriteria(updatedCriteria)

    try {
      const token = localStorage.getItem("token")
      await axios.put(
        `${process.env.REACT_APP_API_URL}/api/criteria/${criteriaId}`,
        { cases: updatedCriteria.find((c) => c._id === criteriaId).cases },
        { headers: { Authorization: `Bearer ${token}` } },
      )
    } catch (error) {
      console.error("Erreur lors de la mise à jour du critère:", error)
      setError("Échec de la mise à jour. Les modifications peuvent ne pas être enregistrées.")
      fetchCriteria() // Rafraîchir les données pour synchroniser avec le serveur
    }
  }

  // Gérer les changements dans les points
  const handlePointsChange = async (criteriaId, caseIndex, newPoints) => {
    const updatedCriteria = criteria.map((criterion) =>
      criterion._id === criteriaId
        ? {
            ...criterion,
            cases: criterion.cases.map((c, i) => (i === caseIndex ? { ...c, points: newPoints } : c)),
          }
        : criterion,
    )
    setCriteria(updatedCriteria)

    try {
      const token = localStorage.getItem("token")
      await axios.put(
        `${process.env.REACT_APP_API_URL}/api/criteria/${criteriaId}`,
        { cases: updatedCriteria.find((c) => c._id === criteriaId).cases },
        { headers: { Authorization: `Bearer ${token}` } },
      )
    } catch (error) {
      console.error("Erreur lors de la mise à jour du critère:", error)
      setError("Échec de la mise à jour. Les modifications peuvent ne pas être enregistrées.")
      fetchCriteria() // Rafraîchir les données pour synchroniser avec le serveur
    }
  }

  // Gérer l'édition d'un critère
  const handleEditCriterion = (criterion) => {
    setSelectedCriterion(criterion)
    setIsEditModalOpen(true)
  }

  // Gérer la création d'un nouveau critère
  const handleCreateCriterion = () => {
    setIsCreateModalOpen(true)
  }

  // Gérer la mise à jour d'un critère après édition
  const handleUpdateCriterion = (updatedCriterion) => {
    setCriteria((prev) => prev.map((c) => (c._id === updatedCriterion._id ? updatedCriterion : c)))
    setIsEditModalOpen(false)
  }

  // Gérer la création d'un critère après soumission
  const handleCreateCriterionSubmit = (newCriterion) => {
    setCriteria((prev) => [...prev, newCriterion])
    setIsCreateModalOpen(false)
  }

  // Gérer la suppression d'un critère
  const handleDeleteCriterion = async (criteriaId) => {
    const isConfirmed = window.confirm("Êtes-vous sûr de vouloir supprimer ce critère ?")
    if (!isConfirmed) return

    try {
      const token = localStorage.getItem("token")
      await axios.delete(`${process.env.REACT_APP_API_URL}/api/criteria/${criteriaId}`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      setCriteria((prev) => prev.filter((c) => c._id !== criteriaId))
    } catch (error) {
      setError("Échec de la suppression du critère. Veuillez réessayer.")
    }
  }

  // Filtrer les critères en fonction du terme de recherche
  const filteredCriteria = criteria.filter(
    (criterion) =>
      criterion.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      criterion.cases.some((c) => c.description.toLowerCase().includes(searchTerm.toLowerCase())),
  )

  return (
    <Layout>
      <div className="max-w-6xl mx-auto px-4 sm:px-6 py-4 sm:py-6">
        <div className="bg-white rounded-xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          {/* Section d'en-tête */}
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-4 sm:p-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                <h2 className="text-xl sm:text-2xl font-bold tracking-tight">Gestion des critères d'évaluation</h2>
                <p className="text-white/80 mt-1 text-xs sm:text-sm">Modifiez les critères et leurs points associés</p>
              </div>
              <button
                onClick={handleCreateCriterion}
                className="px-4 py-2 bg-white text-[#00717F] rounded-md shadow-sm hover:bg-gray-100 flex items-center gap-2 text-xs sm:text-sm font-medium"
              >
                <Plus className="h-4 w-4" />
                Créer un critère
              </button>
            </div>
          </div>

          {/* Barre de recherche et de filtre */}
          <div className="p-4 sm:p-6">
            <div className="mb-4 sm:mb-6 flex flex-col sm:flex-row gap-3 sm:gap-4">
              <div className="relative flex-1">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-4 w-4 sm:h-5 sm:w-5 text-gray-400" />
                </div>
                <input
                  type="text"
                  placeholder="Rechercher des critères..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="block w-full pl-10 pr-3 py-2 sm:py-2.5 border border-[#C8A45D/30] rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F] text-sm"
                />
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={fetchCriteria}
                  className="px-3 py-2 sm:py-2.5 border border-[#C8A45D/30] rounded-md shadow-sm hover:bg-[#F5F6FA] text-xs sm:text-sm text-gray-700 flex items-center gap-2"
                >
                  <Loader2 className="h-3 w-3 sm:h-4 sm:w-4" />
                  Actualiser
                </button>
              </div>
            </div>

            {/* Afficher le message d'erreur s'il y en a */}
            {error && (
              <div className="p-3 sm:p-4 m-3 sm:m-4 rounded-r-md bg-red-50 border-l-4 border-red-500 flex items-center gap-3">
                <AlertCircle className="h-4 w-4 sm:h-5 sm:w-5 text-red-500 flex-shrink-0" />
                <p className="text-xs sm:text-sm text-red-700">{error}</p>
              </div>
            )}

            {/* Indicateur de chargement */}
            {isLoading ? (
              <div className="flex justify-center items-center h-48 sm:h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-8 w-8 sm:h-10 sm:w-10 text-[#00717F] animate-spin" />
                  <p className="text-[#00717F] text-xs sm:text-sm font-medium">Chargement des critères...</p>
                </div>
              </div>
            ) : filteredCriteria.length === 0 ? (
              <div className="flex justify-center items-center h-48 sm:h-64 flex-col gap-2 text-gray-500">
                <Filter className="h-10 w-10 sm:h-12 sm:w-12 text-gray-300" />
                <p className="text-center text-sm sm:text-base">Aucun critère trouvé</p>
                {searchTerm && (
                  <button
                    onClick={() => setSearchTerm("")}
                    className="text-[#00717F] hover:underline text-xs sm:text-sm"
                  >
                    Effacer la recherche
                  </button>
                )}
              </div>
            ) : (
              /* Tableau des critères */
              <div className="overflow-x-auto">
                <table className="w-full border-collapse">
                  <thead>
                    <tr className="bg-[#F5F6FA] border-b border-[#C8A45D/30]/50">
                      <th className="text-left py-3 px-4 font-semibold text-[#00717F] text-xs sm:text-sm">Nom</th>
                      <th className="text-left py-3 px-4 font-semibold text-[#00717F] text-xs sm:text-sm">Cas</th>
                      <th className="text-left py-3 px-4 font-semibold text-[#00717F] text-xs sm:text-sm w-24">
                        Points
                      </th>
                      <th className="text-left py-3 px-4 font-semibold text-[#00717F] text-xs sm:text-sm w-32">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredCriteria.map((criterion) => (
                      <tr key={criterion._id} className="border-b border-[#C8A45D/30]/30 hover:bg-[#F5F6FA]/50">
                        <td className="py-3 px-4 align-top">
                          <div className="font-medium text-gray-900 text-xs sm:text-sm">{criterion.name}</div>
                        </td>
                        <td className="py-3 px-4">
                          <ul className="space-y-2">
                            {criterion.cases.map((c, index) => (
                              <li key={index} className="flex items-center gap-2">
                                <input
                                  type="text"
                                  value={c.description}
                                  onChange={(e) => handleDescriptionChange(criterion._id, index, e.target.value)}
                                  className="w-full px-3 py-1.5 sm:py-2 border border-[#C8A45D/30] rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F] text-xs sm:text-sm"
                                />
                              </li>
                            ))}
                          </ul>
                        </td>
                        <td className="py-3 px-4">
                          <ul className="space-y-2">
                            {criterion.cases.map((c, index) => (
                              <li key={index} className="flex items-center gap-2">
                                <input
                                  type="number"
                                  value={c.points}
                                  onChange={(e) =>
                                    handlePointsChange(criterion._id, index, Number.parseInt(e.target.value) || 0)
                                  }
                                  className="w-full px-3 py-1.5 sm:py-2 border border-[#C8A45D/30] rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F] text-xs sm:text-sm"
                                />
                              </li>
                            ))}
                          </ul>
                        </td>
                        <td className="py-3 px-4">
                          <div className="flex items-center gap-2">
                            <button
                              onClick={() => handleEditCriterion(criterion)}
                              className="p-1.5 sm:p-2 text-[#00717F] hover:bg-[#00717F]/10 rounded-full transition-colors"
                              aria-label="Éditer"
                            >
                              <Edit className="h-3 w-3 sm:h-4 sm:w-4" />
                            </button>
                            <button
                              onClick={() => handleDeleteCriterion(criterion._id)}
                              className="p-1.5 sm:p-2 text-red-600 hover:bg-red-50 rounded-full transition-colors"
                              aria-label="Supprimer"
                            >
                              <Trash2 className="h-3 w-3 sm:h-4 sm:w-4" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Modal d'édition de critère */}
      <EditCriterionModal
        criterion={selectedCriterion}
        isOpen={isEditModalOpen}
        onClose={() => {
          setIsEditModalOpen(false)
        }}
        onUpdate={handleUpdateCriterion}
      />

      {/* Modal de création de critère */}
      <CreateCriterionModal
        isOpen={isCreateModalOpen}
        onClose={() => {
          setIsCreateModalOpen(false)
        }}
        onCreate={handleCreateCriterionSubmit}
      />
    </Layout>
  )
}
